message.content:
⚡ Get-ChildItem -Force | Select-Object Mode, Name
Get-ChildItem -Path . -Filter AGENTS.md -File | ForEach-Object { Get-Content -LiteralPath $_.FullName }
Get-ChildItem -LiteralPath data -Recurse -File | Select-Object FullName, Length
Get-ChildItem -LiteralPath data -Recurse -File | Where-Object { $_.Extension -in '.scn', '.tif', '.tiff' } | ForEach-Object {
  $stream = [System.IO.File]::OpenRead($_.FullName)
  try {
    $buffer = New-Object byte[] 64
    $count = $stream.Read($buffer, 0, $buffer.Length)
    [PSCustomObject]@{ File = $_.FullName; HeaderHex = [System.BitConverter]::ToString($buffer, 0, $count); HeaderText = [System.Text.Encoding]::ASCII.GetString($buffer, 0, $count) }
  } finally { $stream.Dispose() }
} → ✅ exit 0 · 0s

⚡ $rootItems = @(Get-ChildItem -Force | Select-Object Mode, Name)
ConvertTo-Json -InputObject $rootItems -Compress
$dataFiles = @(Get-ChildItem -LiteralPath data -Recurse -File | Select-Object FullName, Length)
ConvertTo-Json -InputObject $dataFiles -Compress
Get-ChildItem -LiteralPath data -Recurse -File | Where-Object { $_.Extension -in '.scn', '.tif', '.tiff' } | ForEach-Object {
  $stream = [System.IO.File]::OpenRead($_.FullName)
  try {
    $buffer = New-Object byte[] 128
    $count = $stream.Read($buffer, 0, $buffer.Length)
    [PSCustomObject]@{ File = $_.FullName; HeaderHex = [System.BitConverter]::ToString($buffer, 0, $count); HeaderText = [System.Text.Encoding]::ASCII.GetString($buffer, 0, $count) } | ConvertTo-Json -Compress
  } finally { $stream.Dispose() }
}
Get-Command python, py -ErrorAction SilentlyContinue | Select-Object Name, Source | ConvertTo-Json -Compress → ✅ exit 0 · 0s
